def verify_stream(raw, model, side):
    x, y = np.meshgrid(np.arange(48, 272), np.arange(8, 232))
    r, g, b = (3 * x + y // 3) % 32, (x // 7 + 5 * y) % 64, (x // 4 + 3 * y) % 32
    packed = ((r << 11) | (g << 5) | b).astype(np.uint16)
    pattern = downsample_roi(channels(packed, display=True), side)[::-1]
    ref = next(
        row
        for row in read_records()
        if row["kind"] == "reference" and row["class_id"] == 7
    )
    expected_pixels = (
        pattern,
        input_pixels(ref["file"], "card", side),
        np.full((side, side), 65535, np.uint16),
    )
    decoder, twin = PacketParser(side), Twin(model)
    frames = []
    for start in range(0, len(raw), 71):
        frames.extend(decoder.feed(raw[start : start + 71]))
    assert len(frames) == 3 and not decoder.rejected and not decoder.buffer
    for i, (frame, expected) in enumerate(zip(frames, expected_pixels)):
        np.testing.assert_array_equal(frame.pixels, expected)
        pred, _ = twin.classify(expected)
        assert frame.sequence == i + 1 and frame.cycles > 0
        assert (frame.score, frame.wire_id, frame.status) == (
            pred.score,
            pred.wire_id,
            pred.status,
        )
    assert frames[1].wire_id == 6 and all(f.status == 1 for f in frames)
    assert len({f.cycles for f in frames}) == 1

    packet = decoder.packet_size
    damaged = bytearray(raw[:packet])
    damaged[31] ^= 1
    d = PacketParser(side)
    assert not d.feed(b"garbageNP")
    assert not d.feed(d.magic[2:] + damaged[4:] + raw[packet : packet + 2])
    assert [f.sequence for f in d.feed(raw[packet + 2 :])] == [2, 3] and d.rejected == 1
    return [
        dict(
            sequence=f.sequence,
            wire_id=f.wire_id,
            status=f.status,
            score=f.score,
            cycles=f.cycles,
        )
        for f in frames
    ]


def unpack_roms(directory, widths, shifts):
    def signed_rows(name, bits, lanes):
        lines = (directory / name).read_text("ascii").splitlines()
        if any(len(s) != lanes * bits // 4 for s in lines):
            raise ValueError(f"Bad lane width in {name}")
        dtype = np.int8 if bits == 8 else np.int32
        packed = b"".join(bytes.fromhex(s)[::-1] for s in lines)
        return np.frombuffer(packed, dtype=dtype).reshape(-1, lanes)

    q = dict(shifts=np.asarray(shifts))
    sizes = (3, *widths)
    for i, name in enumerate(("conv0", "conv1", "conv2", "conv3", "fc")):
        out = widths[i] if i < 4 else 15
        tag = str(i) if i < 4 else "f"
        w = signed_rows(name + "_weights.mem", 8, out).T
        q["w" + tag] = w.reshape(out, sizes[i], 3, 3) if i < 4 else w
        q["b" + tag] = signed_rows(name + "_bias.mem", 32, out).ravel()
    return q


